// run.mjs supplies it; this command never runs a model or refreshes a catalog.
import { createHash } from 'node:crypto';

// Exercise the public checker against real installed/rebuilt artifacts.
// These failure cases precede its implementation; no oracle is invoked.
import { readFileSync, writeFileSync, mkdtempSync, rmSync, existsSync } from 'node:fs';

// E2E at the run.mjs CLI: replace its external network/filesystem with faulting
// boundary doubles. No verifier function is imported or tested in isolation.
import { readFileSync, writeFileSync, mkdtempSync, rmSync } from 'node:fs';

// Disposable equivalence verification per ADR-0004. No model generation or
// oracle execution occurs. All installs skip lifecycle scripts.
import { createHash } from 'node:crypto';

